const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').trim();
const userName = body.userName || 'User';
const conversationId = body.conversationId || 'default';
const callbackUrl = body.callbackUrl || '';
const attachments = body.attachments || [];

let userMessage = null;
try {
  const parsed = JSON.parse(message);
  if (parsed.intent === 'new_presale') {
    userMessage = 'I want to start a new presale.';
  } else if (parsed.intent === 'continue_presale') {
    userMessage = 'I want to continue working on an existing presale. Please show me the list.';
  }
} catch (_) {}

if (!userMessage) {
  const parts = [];
  if (message) parts.push(message);
  for (const att of attachments) {
    if (att.name && att.content) {
      parts.push(`\n[Attached file: ${att.name}, ${Math.round((att.sizeBytes || 0) / 1024)} KB]`);
    } else if (att.name) {
      parts.push(`\n[File attached (could not be downloaded): ${att.name}]`);
    }
  }
  userMessage = parts.join('\n') || `Hello from ${userName}`;
}

const userId = body.userId || body.from?.id || '';
const aadObjectId = body.aadObjectId || body.from?.aadObjectId || '';
return [{ json: { userMessage, rawMessage: message, conversationId, callbackUrl, userName, userId, aadObjectId, attachments } }];

const input = $input.first().json;
const prep = $('Prepare Input').item.json;
const output = {
  conversationId: prep.conversationId,
  reply: (input.output || '').trim() || 'I could not generate a response. Please try again.',
  callbackUrl: prep.callbackUrl
};

// Detect if the AI is asking the "new vs continue" question
const reply = output.reply;
const isSelectionQuestion = /\b(новый пресейл|нового пресейла|существующий|continue existing|start a new|new presale|create a new|existing one|существующего|продолжить)\b/i.test(reply) &&
  /\b(выбрать|choose|хотите|want|would you|хотите|начать|start)\b/i.test(reply);

if (isSelectionQuestion) {
  output.attachments = [{
    contentType: "application/vnd.microsoft.card.adaptive",
    content: {
      type: "AdaptiveCard",
      version: "1.5",
      body: [
        {
          type: "TextBlock",
          size: "Medium",
          weight: "Bolder",
          text: "🤖 Presale Processing Agent"
        },
        {
          type: "TextBlock",
          text: reply,
          wrap: true
        }
      ],
      actions: [
        {
          type: "Action.Submit",
          title: "🆕 Start a new presale",
          data: { intent: "new_presale" }
        },
        {
          type: "Action.Submit",
          title: "📋 Continue an existing presale",
          data: { intent: "continue_presale" }
        }
      ]
    }
  }];
}

return [{ json: output }];

